package vn.vht.qtkhcn.identity.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="audit_log") public class AuditLog { @Id public UUID id; @Column(name="event_type",nullable=false,length=64) public String eventType; @Column(name="actor_id") public String actorId; @Column(name="entity_type",length=64) public String entityType; @Column(name="entity_id") public String entityId; public String details; @Column(name="occurred_at",nullable=false) public Instant occurredAt; protected AuditLog(){} public AuditLog(String eventType,String entityType,String entityId,String details){id=UUID.randomUUID();this.eventType=eventType;actorId="system";this.entityType=entityType;this.entityId=entityId;this.details=details;occurredAt=Instant.now();} }
